func queryPolicyVerb(action string) string {
	if action == "block" {
		return "Block"
	}
	return "Allow"
}

// queryPolicyApplies says whether an action applies to a query: Block unless
// it was blocked, Allow for everyone unless the rule set's own domain or app
// blocked it, which only the rule set's allowed domains get past, and the
// rule set's versions only when the device used one.
func queryPolicyApplies(entry QueryLogEntryView, action string, forRuleSet bool) bool {
	if forRuleSet && entry.Decision.RuleSet == "" {
		return false
	}
	switch {
	case action == "block":
		return entry.Source != "blocked"
	case forRuleSet:
		return entry.Source == "blocked"
	default:
		return !entry.Decision.RuleSetBlock
	}
}

// queryPolicyLabel names a query panel's Block or Allow: plain when the
// device used no rule set, and for whom when it did.
func queryPolicyLabel(verb, ruleSet string, forRuleSet bool) string {
	switch {
	case ruleSet == "":
		return verb
	case forRuleSet:
		return verb + " for " + ruleSet
	default:
		return verb + " for Everyone"
	}
}

